  const render=()=>{applyContentClarity();const l=lang(),t=copy[l],f=services.flagship;const heroPricePair=(description,value)=>`<div class="service-atlas__hero-price-pair"><div class="service-atlas__hero-price-description">${esc(description)}</div><div class="service-atlas__price service-atlas__hero-price">${priceMarkup(value)}</div></div>`;const heroPricePairs=[[l==='en'?'Commercial activities — Starting at':'سعر الخدمة للأنشطة التجارية يبدأ من','999,000 IQD'],[l==='en'?'Engineering activities — Starting at':'سعر الخدمة للأنشطة الهندسية يبدأ من',f.price[l]]];const chapter=(item,type,image)=>`<section class="service-atlas__section service-atlas__chapter ${type==='identity'?'service-atlas__chapter--identity':''}" aria-labelledby="${item.id}-title"><div class="service-atlas__chapter-visual service-atlas__chapter-visual--${type}" aria-hidden="true"><img class="service-atlas__service-image" src="${image}" alt="" loading="lazy" decoding="async"></div><div><p class="service-atlas__eyebrow">${esc(item[l].eyebrow)}</p><h2 class="service-atlas__title" id="${item.id}-title">${esc(item[l].title)}</h2><p class="service-atlas__lead">${esc(item[l].lead)}</p><p class="service-atlas__chapter-price">${esc(item.price[l])}</p><ul class="service-atlas__deliverables">${item.deliverables[l].map((x)=>`<li>${esc(x)}</li>`).join('')}</ul><div class="service-atlas__actions">${button(item.id,t.request)}</div></div></section>`;
    app.innerHTML=`<section class="service-atlas__section service-atlas__hero" aria-labelledby="services-title"><div class="service-atlas__hero-grid"><div class="service-atlas__hero-copy"><p class="service-atlas__eyebrow">${esc(f[l].eyebrow)}</p><h1 class="service-atlas__title service-atlas__hero-title" id="services-title">${esc(f[l].title)}</h1><p class="service-atlas__lead">${esc(f[l].lead)}</p><div class="service-atlas__hero-price-grid" aria-label="${esc(l==='en'?'Service prices':'أسعار الخدمة')}">${heroPricePairs.map(([description,value])=>heroPricePair(description,value)).join('')}</div><div class="service-atlas__actions"><button class="service-atlas__button" type="button" data-scroll-to="brand-scope">${esc(t.viewScope)}</button>${button(f.id,t.request)}</div></div></div></section><section class="service-atlas__section service-atlas__scope" id="brand-scope" aria-labelledby="scope-title"><div class="service-atlas__scope-list">${f.scope[l].map((x,i)=>`<article class="service-atlas__scope-item"><span class="service-atlas__scope-number">0${i+1}</span><div><h3 class="service-atlas__scope-name">${esc(x[0])}</h3><p class="service-atlas__scope-description">${esc(x[1])}</p><ul class="service-atlas__scope-points">${x[2].map((p)=>`<li>${esc(p)}</li>`).join('')}</ul></div></article>`).join('')}<div class="service-atlas__actions">${button(f.id,t.request)}</div></div></section>${chapter(services.creation,'creation','/assets/projects/alfares/01.webp')}${chapter(services.identity,'identity','/assets/projects/velvet/01.webp')}<section class="service-atlas__section service-atlas__small" aria-labelledby="small-title"><div class="service-atlas__small-head"><div><p class="service-atlas__eyebrow">${esc(t.smallEyebrow)}</p><h2 class="service-atlas__title" id="small-title">${esc(t.smallTitle)}</h2></div><p class="service-atlas__lead">${esc(t.smallLead)}</p></div><div class="service-atlas__small-list">${services.small.map((x)=>`<article class="service-atlas__small-item"><h3 class="service-atlas__small-name">${esc(l==='en'?x[4]:x[5])}</h3><p class="service-atlas__small-detail">${esc(l==='en'?x[2]:x[3])}</p><span class="service-atlas__small-price">${esc(`${t.from} ${x[1]}`)}</span></article>`).join('')}</div></section><section class="service-atlas__section service-atlas__technical" aria-labelledby="technical-title"><div><p class="service-atlas__eyebrow">${esc(t.technicalEyebrow)}</p><h2 class="service-atlas__title" id="technical-title">${esc(t.technicalTitle)}</h2><p class="service-atlas__lead">${esc(t.technicalLead)}</p><p class="service-atlas__technical-note">${esc(t.technicalNote)}</p></div><div class="service-atlas__technical-list">${services.technical.map((x,i)=>`<article class="service-atlas__technical-item"><h3 class="service-atlas__technical-name">${esc(l==='en'?x[2]:x[4])}</h3><p class="service-atlas__technical-description">${esc(technicalDescriptions[l][i])}</p><span class="service-atlas__technical-price">${esc(l==='en'?x[1]:x[3])}</span><div class="service-atlas__actions">${button(x[0],t.request)}</div></article>`).join('')}</div></section><section class="service-atlas__section service-atlas__partners" aria-labelledby="partners-title"><div class="service-atlas__partner-surface"><div class="service-atlas__partner-head"><div><p class="service-atlas__eyebrow">${esc(t.partnersEyebrow)}</p><h2 class="service-atlas__title" id="partners-title">${esc(t.partnersTitle)}</h2></div><p class="service-atlas__price">${esc(t.custom)}</p></div><div class="service-atlas__partner-list">${services.partners.map((x)=>`<article class="service-atlas__partner-item"><h3>${esc(l==='en'?x[1]:x[3])}</h3><p>${esc(l==='en'?x[2]:x[4])}</p><div class="service-atlas__partner-actions"><button class="service-atlas__button service-atlas__button--blue service-atlas__partner-request" type="button" data-request-service="${x[0]}">${esc(t.requestShort)}</button></div></article>`).join('')}</div><p class="service-atlas__coming-soon">${esc(t.comingSoon)}</p></div></section><section class="service-atlas__section service-atlas__gallery" aria-labelledby="gallery-title"><div class="service-atlas__gallery-wrap"><p class="service-atlas__eyebrow">${esc(t.galleryEyebrow)}</p><h2 class="service-atlas__title" id="gallery-title">${esc(t.galleryTitle)}</h2><p class="service-atlas__lead">${esc(t.galleryLead)}</p><div class="service-atlas__gallery-deck" aria-hidden="true"></div><div class="service-atlas__actions" style="justify-content:center"><a class="service-atlas__button" href="/gallery">${esc(t.galleryAction)}</a></div></div></section><section class="service-atlas__section service-atlas__request" id="service-request" aria-labelledby="request-title"><div class="service-atlas__request-wrap"><div class="service-atlas__request-intro"><p class="service-atlas__eyebrow">${esc(t.requestEyebrow)}</p><h2 class="service-atlas__title" id="request-title">${esc(t.requestTitle)}</h2><p class="service-atlas__lead">${esc(t.requestLead)}</p><div class="service-atlas__contact-links"><a class="service-atlas__contact-button" href="tel:07840440011">${esc(t.phone)}</a><a class="service-atlas__contact-button" href="mailto:hello@ooxme.com">${esc(t.email)}</a><a class="service-atlas__contact-button" href="https://wa.me/9647840440011" target="_blank" rel="noopener noreferrer">${esc(t.whatsapp)}</a></div></div><form class="service-atlas__request-form" data-service-request novalidate><div class="service-atlas__field"><label for="request-service">${esc(t.service)}</label><select id="request-service" name="service">${choices(l)}</select></div><div class="service-atlas__field"><label for="request-name">${esc(t.name)}</label><input id="request-name" name="name" autocomplete="name" required></div><div class="service-atlas__field"><label for="request-contact">${esc(t.contact)}</label><input id="request-contact" name="contact" autocomplete="email" required></div><div class="service-atlas__field"><label for="request-business">${esc(t.business)}</label><input id="request-business" name="business"></div><div class="service-atlas__field"><label for="request-details">${esc(t.details)}</label><textarea id="request-details" name="details" required></textarea></div><button class="service-atlas__button service-atlas__button--blue" type="submit">${esc(t.send)}</button><p class="service-atlas__form-note">${esc(t.fallback)}</p><p class="service-atlas__form-status" data-request-status role="status"></p></form></div></section>`;applyContentClarity();};
  const nameFor=(id,l)=>{if(services.flagship.id===id)return services.flagship[l].title;if(services.creation.id===id)return services.creation[l].title;if(services.identity.id===id)return services.identity[l].title;const a=services.small.find(x=>x[0]===id);if(a)return l==='en'?a[4]:a[5];const b=services.technical.find(x=>x[0]===id);if(b)return l==='en'?b[2]:b[4];const c=services.partners.find(x=>x[0]===id);return c?(l==='en'?c[1]:c[3]):id;};
  const selectService=(id)=>{const select=app.querySelector('[name="service"]'),form=app.querySelector('[data-service-request]');if(!select||!form)return;select.value=id;form.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'center'});window.setTimeout(()=>app.querySelector('#request-name')?.focus({preventScroll:true}),350);};
  app.addEventListener('click',(event)=>{const accordion=event.target.closest('[data-atlas-accordion-question]');if(accordion){const shouldOpen=accordion.getAttribute('aria-expanded')!=='true';app.querySelectorAll('[data-atlas-accordion-question]').forEach((item)=>{const open=item===accordion&&shouldOpen;item.setAttribute('aria-expanded',String(open));item.classList.toggle('is-open',open);item.closest('.service-atlas__small-item,.service-atlas__scope-item')?.classList.toggle('is-open',open);const answer=document.getElementById(item.getAttribute('aria-controls'));answer?.setAttribute('aria-hidden',String(!open));});return;}const request=event.target.closest('[data-request-service]');if(request){selectService(request.dataset.requestService);return;}const scroll=event.target.closest('[data-scroll-to]');if(scroll)document.getElementById(scroll.dataset.scrollTo)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});});
  app.addEventListener('submit',(event)=>{const form=event.target.closest('[data-service-request]');if(!form)return;event.preventDefault();const l=lang(),t=copy[l],data=new FormData(form),status=form.querySelector('[data-request-status]');if(!data.get('name')?.trim()||!data.get('contact')?.trim()||!data.get('details')?.trim()){status.textContent=t.required;return;}const selected=nameFor(data.get('service'),l);const body=[`${t.service}: ${selected}`,`${t.name}: ${data.get('name').trim()}`,`${t.contact}: ${data.get('contact').trim()}`,`${t.business}: ${data.get('business').trim()||'-'}`,'',`${t.details}:`,data.get('details').trim()].join('\n');status.textContent=t.status;window.location.href=`mailto:hello@ooxme.com?subject=${encodeURIComponent(`${t.emailSubject}: ${selected}`)}&body=${encodeURIComponent(body)}`;});
  let accordionSerial=0;
  const removeServiceImages=()=>{app.querySelectorAll('.service-atlas__service-image').forEach((image)=>image.remove());};
  const removeScopeNumbers=()=>{app.querySelectorAll('.service-atlas__scope-number').forEach((number)=>number.remove());};
  const technicalDescriptions={en:['Creation, design, and development of a single web page to present your business, product, or service, with clearly organized content, sections, and contact options for easy use.','Creation, design, and development of a website with connected pages to present your business information, services, and work, with content and navigation structured around your project\'s needs.','Design and development of a mobile application based on project requirements, including the interfaces, features, and interactions needed for a clear and organized user experience.'],ar:['إنشاء وتصميم وتطوير صفحة ويب واحدة لعرض نشاطك أو منتجك أو خدمتك، مع تنظيم المحتوى والأقسام ووسائل التواصل بطريقة واضحة وسهلة الاستخدام.','إنشاء وتصميم وتطوير موقع إلكتروني يضم صفحات مترابطة لعرض معلومات نشاطك وخدماتك وأعمالك، مع تنظيم المحتوى والتنقل بين الصفحات بما يناسب احتياجات المشروع.','تصميم وتطوير تطبيق للهواتف الذكية وفق متطلبات المشروع، مع بناء الواجهات والوظائف والتفاعلات اللازمة لتقديم تجربة استخدام واضحة ومنظمة.']};
  const partnerDescriptions={en:['Production of printed and promotional materials, including stationery, brochures, posters, signage, and display materials, coordinated with printing and production providers according to the required quantities and specifications.','Coordination of transport, delivery, shipping, loading, and installation services, as well as project-related logistics, based on location, scale, and material requirements.','Coordination with designers, photographers, content creators, voice-over artists, models, and other specialists to deliver creative and production work based on project needs.','Coordination of furniture, décor, interior and exterior fit-out services, including the preparation of offices, retail stores, and commercial spaces, along with related materials and equipment.','Assistance with coordinating the sourcing of products, materials, and equipment, and communicating with suppliers and providers involved in purchasing, shipping, and logistics locally and internationally, according to each request.'],ar:['تنفيذ المطبوعات والمواد الدعائية مثل القرطاسية والمنشورات والملصقات واللافتات ومواد العرض، بالتنسيق مع مزودي الطباعة والإنتاج وفق الكميات والمواصفات المطلوبة.','تنسيق خدمات النقل والتوصيل والشحن والتحميل والتركيب، إلى جانب المتطلبات اللوجستية المرتبطة بالأعمال والمشاريع، بحسب الموقع وحجم العمل وطبيعة المواد.','التنسيق مع المصممين والمصورين وصناع المحتوى والمعلقين الصوتيين والعارضين وغيرهم من المتخصصين، لتنفيذ الأعمال الإبداعية والإنتاجية وفق احتياجات المشروع.','تنسيق خدمات الأثاث والديكور والتجهيز الداخلي والخارجي، بما يشمل تجهيز المكاتب والمتاجر والمساحات التجارية والمواد والمعدات المرتبطة بها.','المساعدة في تنسيق توريد المنتجات والمواد والمعدات، والتواصل مع الموردين ومقدمي الخدمات المرتبطة بالشراء والشحن والمعالجة اللوجستية محليًا ودوليًا، وفق متطلبات الطلب.']};
  const applyApprovedSmallServices=()=>{const approved=[['Documents & Presentations','تصميم الملفات والعروض','Creation, design, and formatting of documents used to present your business and information clearly, including company profiles, presentations, reports, catalogs, and digital documents. Text and images are organized for easy reading and use.','إنشاء وتصميم وتنسيق الملفات التي تستخدمها في تقديم أعمالك ومعلوماتك بشكل مرتب وواضح، مثل عروض الشركات والعروض التقديمية والتقارير والكتالوجات والملفات الرقمية، مع تنظيم النصوص والصور لتكون سهلة القراءة والاستخدام.'],['Forms & Documents','تصميم النماذج والمستندات','Creation and design of everyday business forms and documents, including invoices, certificates, administrative forms, and internal documents, with clearly organized information and fields that are easy to complete and read.','إنشاء وتصميم النماذج والمستندات التي تحتاجها في أعمالك اليومية، مثل الفواتير والشهادات والنماذج الإدارية والوثائق الداخلية، مع ترتيب المعلومات والحقول بطريقة واضحة تسهّل تعبئتها وقراءتها.'],['Menus & Price Lists','تصميم القوائم والأسعار','Creation and design of food menus, drink menus, service lists, and price lists, with clearly arranged sections, names, details, and prices that help customers understand their options and choose what suits them.','إنشاء وتصميم قوائم الطعام والمشروبات والخدمات والأسعار بطريقة منظمة وسهلة الفهم، مع توزيع الأقسام والأسماء والتفاصيل والأسعار بشكل يساعد العملاء على الاطلاع على الخيارات واختيار ما يناسبهم.'],['Card Design','تصميم البطاقات','Creation and design of business cards, identification cards, employee cards, and badges, with names, information, logos, and visual elements arranged for professional use and printing.','إنشاء وتصميم بطاقات الأعمال والتعريف وبطاقات الموظفين والشارات، مع ترتيب الأسماء والمعلومات والشعارات والعناصر البصرية بطريقة مناسبة للاستخدام المهني والطباعة.'],['CVs & Signatures','السير الذاتية والتواقيع','Creation, design, and formatting of CVs, cover letters, and email signatures, with personal information, professional details, and contact information organized clearly for their intended use.','إنشاء وتصميم وتنسيق السير الذاتية وخطابات التقديم والتواقيع الإلكترونية، مع تنظيم المعلومات الشخصية والمهنية وبيانات التواصل لتظهر بشكل واضح ومرتب يناسب استخدامها.'],['Icons & Symbols','تصميم الأيقونات والرموز','Creation and design of icons, symbols, and small visual elements for your accounts and digital materials, including service-category icons, information icons, and graphic elements that follow your brand\'s visual style.','إنشاء وتصميم الأيقونات والرموز والعناصر البصرية الصغيرة التي تحتاجها في حساباتك وموادك الرقمية، مثل رموز أقسام الخدمات وأيقونات المعلومات والعناصر المستخدمة في التصاميم، مع مراعاة أسلوب علامتك البصري.']];approved.forEach((item,index)=>{const service=services.small[index];service[2]=item[2];service[3]=item[3];service[4]=item[0];service[5]=item[1];});};
  const applyContentClarity=()=>{services.flagship.en.lead='We manage your brand and continuously develop its presence, from defining its direction and organizing its messaging and identity to improving content, marketing, and customer experience. We align these areas with your business goals to build a consistent presence, communicate more clearly with your audience, and support growth through informed decisions.';services.flagship.ar.lead='نتولى إدارة علامتك التجارية وتطوير حضورها بشكل مستمر، من تحديد توجهها وتنظيم رسائلها وهويتها، إلى تحسين المحتوى والتسويق وتجربة العملاء. نعمل على ربط هذه الجوانب بأهداف نشاطك التجاري، لضمان ظهور متناسق، وتواصل أوضح مع جمهورك، وقرارات مدروسة تدعم نمو أعمالك.';services.flagship.scope.en[0][1]='We define the brand’s position and message, then set clear rules the team can use consistently.';services.flagship.scope.ar[0][1]='نحدد مكانة العلامة ورسالتها، ثم نضع قواعد واضحة يستطيع الفريق استخدامها بثبات.';services.flagship.scope.en[1][1]='We turn brand goals into practical steps that improve sales, offers, and the customer experience.';services.flagship.scope.ar[1][1]='نحوّل أهداف العلامة إلى خطوات عملية تحسن المبيعات والعروض وتجربة العميل.';services.flagship.scope.en[2][1]='We plan the content and campaigns the brand needs, with the direction and production required for a clear presence.';services.flagship.scope.ar[2][1]='نخطط للمحتوى والحملات التي تحتاجها العلامة، مع التوجيه والإنتاج اللازمين لحضور واضح.';services.flagship.scope.en[3][1]='We organize the digital and operating systems the brand needs to work efficiently and support growth.';services.flagship.scope.ar[3][1]='نرتب الأنظمة الرقمية والتشغيلية التي تحتاجها العلامة للعمل بكفاءة ودعم نموها.';services.creation.en.lead='We help you build your brand from the ground up, from exploring your idea and defining your business direction to creating the visual identity and launch, marketing, and growth plans. The service includes a comprehensive brand guide, plans to organize and grow your business, and ongoing support during the first 90 days.';services.creation.ar.lead='نساعدك على بناء علامتك التجارية من البداية، من دراسة الفكرة وتحديد اتجاه المشروع إلى إعداد الهوية البصرية وخطط الإطلاق والتسويق والنمو. تشمل الخدمة دليلًا متكاملًا للعلامة التجارية وخططًا لتنظيم العمل وتطويره، مع دعم مستمر خلال أول 90 يومًا.';services.identity.en.lead='We design a complete visual identity that gives your business a clear and consistent appearance. The service includes logos, colors, typography, essential print materials, and social media templates, along with a guide explaining how to use the identity correctly.';services.identity.ar.lead='نصمم هوية بصرية متكاملة تمنح مشروعك مظهرًا واضحًا ومتناسقًا. تشمل الخدمة تصميم الشعارات واختيار الألوان والخطوط وإعداد المطبوعات وقوالب التواصل الاجتماعي الأساسية، مع دليل يوضح كيفية استخدام الهوية بشكل صحيح.';services.small[0][2]='Design for business files, presentations, reports, catalogs, and other digital documents.';services.small[0][3]='تصميم ملفات الأعمال والعروض والتقارير والكتالوجات وغيرها من الوثائق الرقمية.';services.small[1][2]='Design for forms, invoices, certificates, and internal business documents.';services.small[1][3]='تصميم النماذج والفواتير والشهادات والوثائق الداخلية للأعمال.';services.small[2][2]='Design menus, service lists, and price lists that are easy for customers to read.';services.small[2][3]='تصميم القوائم وقوائم الخدمات والأسعار بطريقة سهلة القراءة للعملاء.';services.small[3][2]='Design cards and identification badges for business use.';services.small[3][3]='تصميم البطاقات وبطاقات التعريف للاستخدام في الأعمال.';services.small[4][2]='Design CVs, cover letters, and electronic signatures for professional use.';services.small[4][3]='تصميم السير الذاتية وخطابات التقديم والتواقيع الإلكترونية للاستخدام المهني.';services.small[5][2]='Create icons, symbols, and visual assets for accounts and digital profiles.';services.small[5][3]='إنشاء الأيقونات والرموز والأصول البصرية للحسابات والملفات الرقمية.';technicalDescriptions.en=['Present one business, product, or service through a focused web experience.','Organize business information, services, and content across multiple connected pages.','Provide a dedicated mobile experience with features and interactions defined by the project’s requirements.'];technicalDescriptions.ar=['تقديم نشاط تجاري أو منتج أو خدمة من خلال تجربة ويب مركزة وواضحة.','تنظيم معلومات الأعمال والخدمات والمحتوى عبر صفحات متعددة ومترابطة.','تقديم تجربة مخصصة للهواتف بميزات وتفاعلات يحددها متطلبات المشروع.'];copy.en.technicalNote='Depending on the service, the work may include design, development, responsive behavior, hosting integration, security, and maintenance. External subscriptions and third-party fees are excluded where applicable.';copy.ar.technicalNote='قد يشمل العمل التصميم والتطوير والاستجابة ودمج الاستضافة والأمان والصيانة، بحسب الخدمة. لا تشمل الأسعار الاشتراكات الخارجية ورسوم الجهات الأخرى عند الحاجة.';copy.en.galleryLead='Explore selected OOXME brand identity projects and see how the work is applied in practice.';copy.ar.galleryLead='استكشف مشاريع مختارة من هويات العلامات لدى OOXME وشاهد كيف تُطبّق الأعمال عملياً.';copy.en.requestLead='Choose a service and share the key details of your project. Your email application will open with a prepared request for the OOXME team.';copy.ar.requestLead='اختر خدمة وشارك التفاصيل الأساسية لمشروعك. سيفتح تطبيق البريد لديك بطلب جاهز لفريق OOXME.';services.partners[0][2]='Printing for stationery, publications, posters, advertising signs, and related materials.';services.partners[0][4]='الطباعة للقرطاسية والمنشورات والملصقات واللافتات الإعلانية والمواد ذات الصلة.';services.partners[1][2]='Collection, loading, delivery, installation, and commercial transport coordination.';services.partners[1][4]='الجمع والتحميل والتوصيل والتركيب وتنسيق النقل التجاري.';services.partners[2][2]='Access to designers, voice-over artists, models, photographers, creators, and UGC production.';services.partners[2][4]='توفير المصممين وفناني التعليق الصوتي والعارضين والمصورين وصناع المحتوى وإنتاج محتوى المستخدمين.';services.partners[3][2]='Furniture, interior and exterior decoration, equipment, and preparation of commercial spaces.';services.partners[3][4]='الأثاث والديكور الداخلي والخارجي والمعدات وتجهيز المساحات التجارية.';services.partners[4][2]='Sourcing, purchasing, processing, coordination, and local or international partnerships.';services.partners[4][4]='التوريد والشراء والمعالجة والتنسيق والشراكات المحلية أو الدولية.';};
  applyApprovedSmallServices();
  services.small.forEach((service)=>[2,3,4,5].forEach((index)=>{const value=service[index];Object.defineProperty(service,index,{configurable:false,get:()=>value,set:()=>{}});}));
  const removeTechnicalPartnerRequests=()=>{app.querySelectorAll('.service-atlas__technical-item .service-atlas__actions,.service-atlas__partner-item .service-atlas__partner-actions').forEach((actions)=>actions.remove());};
  const removeComingSoon=()=>{app.querySelector('.service-atlas__coming-soon')?.remove();};
  const removeSmallEyebrow=()=>{app.querySelector('.service-atlas__small-head .service-atlas__eyebrow:empty')?.remove();};
  const normalizeActionButtons=()=>{app.querySelectorAll('.service-atlas__hero [data-scroll-to],.service-atlas__gallery .service-atlas__button,.service-atlas__contact-button').forEach((button)=>{button.classList.add('service-atlas__button','service-atlas__button--blue');button.classList.remove('service-atlas__contact-button','service-atlas__action-width-auto');});};
   const setupGalleryCarousel=()=>{app._galleryCarouselCleanup?.();const deck=app.querySelector('.service-atlas__gallery-deck');if(!deck||deck.dataset.carouselReady)return;const projects=[{folder:'alfares'},{folder:'alsebteen'},{folder:'velvet'},{folder:'zone'},{folder:'sda alrwaq'}];const tileMarkup=projects.map((project)=>{const base=encodeURI('/assets/projects/'+project.folder+'/07');return '<figure class="service-atlas__gallery-tile"><picture><source type="image/avif" srcset="'+base+'.avif"><source type="image/webp" srcset="'+base+'.webp"><img src="'+base+'.webp" width="2175" height="2175" loading="lazy" decoding="async" alt=""></picture></figure>';}).join('');deck.dataset.carouselReady='true';deck.outerHTML='<div class="service-atlas__gallery-carousel" data-gallery-carousel role="region" aria-roledescription="carousel" aria-label="'+(lang()==='ar'?'أعمال مختارة':'Selected works')+'" tabindex="0"><div class="service-atlas__gallery-viewport"><div class="service-atlas__gallery-track" data-gallery-track>'+tileMarkup+tileMarkup+'</div></div></div>';const carousel=app.querySelector('[data-gallery-carousel]'),track=carousel?.querySelector('[data-gallery-track]');if(!carousel||!track)return;[...track.children].slice(projects.length).forEach((tile)=>tile.setAttribute('aria-hidden','true'));let loopWidth=0,offset=0,lastTime=performance.now(),lastX=0,dragging=false,dragged=false,paused=false,destroyed=false;let frameId=0;const speed=24,reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const normalize=()=>{if(!loopWidth)return;while(offset>=loopWidth)offset-=loopWidth;while(offset<0)offset+=loopWidth;};const render=()=>{track.style.transform='translate3d('+(-offset)+'px,0,0)';};const measure=()=>{if(destroyed)return;const tile=track.querySelector('.service-atlas__gallery-tile');if(!tile)return;const tileWidth=tile.getBoundingClientRect().width,gap=parseFloat(getComputedStyle(track).gap)||0;loopWidth=(tileWidth+gap)*projects.length;normalize();render();};const frame=(now)=>{if(destroyed)return;const delta=Math.min(50,Math.max(0,now-lastTime));lastTime=now;if(!dragging&&!paused&&!reduced){offset+=(root.dir==='rtl'?-1:1)*speed*delta/1000;normalize();render();}frameId=requestAnimationFrame(frame);};const endDrag=(event)=>{if(!dragging)return;dragging=false;paused=false;carousel.classList.remove('is-dragging');if(event?.pointerId!==undefined&&carousel.hasPointerCapture?.(event.pointerId))carousel.releasePointerCapture(event.pointerId);};carousel.addEventListener('pointerdown',(event)=>{if(event.pointerType==='mouse'&&event.button!==0)return;dragging=true;dragged=false;paused=true;lastX=event.clientX;carousel.setPointerCapture?.(event.pointerId);carousel.classList.add('is-dragging');});carousel.addEventListener('pointermove',(event)=>{if(!dragging)return;const delta=event.clientX-lastX;lastX=event.clientX;if(Math.abs(delta)>1)dragged=true;offset-=delta;normalize();render();});carousel.addEventListener('pointerup',endDrag);carousel.addEventListener('pointercancel',endDrag);carousel.addEventListener('pointerleave',(event)=>{if(dragging&&event.pointerType==='mouse')endDrag(event);});carousel.addEventListener('mouseenter',()=>{paused=true;});carousel.addEventListener('mouseleave',()=>{if(!dragging)paused=false;});carousel.addEventListener('focusin',()=>{paused=true;});carousel.addEventListener('focusout',()=>{paused=false;});carousel.addEventListener('click',(event)=>{if(dragged){dragged=false;event.preventDefault();return;}if(event.target.closest('.service-atlas__gallery-tile'))window.location.href='/gallery';});measure();let observer=null;if(typeof ResizeObserver==='function'){observer=new ResizeObserver(measure);observer.observe(carousel);}else window.addEventListener('resize',measure,{passive:true});app._galleryCarouselCleanup=()=>{destroyed=true;observer?.disconnect();if(frameId)cancelAnimationFrame(frameId);};frameId=requestAnimationFrame(frame);};
  const normalizeChapterContainers=()=>{app.querySelectorAll('.service-atlas__chapter').forEach((section)=>{const visual=section.querySelector(':scope > .service-atlas__chapter-visual'),content=section.querySelector(':scope > div:not(.service-atlas__chapter-visual)');if(!visual||!content||visual.contains(content))return;visual.removeAttribute('aria-hidden');content.classList.add('service-atlas__chapter-content');visual.append(content);});};
  const makeAccordion=(title,nodes,level)=>{if(!title||!nodes.length||title.closest('[data-atlas-accordion-question]'))return;const parent=title.parentElement,question=document.createElement('button'),heading=document.createElement('span'),toggle=document.createElement('span'),answer=document.createElement('div'),inner=document.createElement('div'),id=`service-atlas-accordion-${++accordionSerial}`;question.type='button';question.className='service-atlas__accordion-question';question.setAttribute('aria-expanded','false');question.setAttribute('aria-controls',id);question.dataset.atlasAccordionQuestion='';heading.className=`service-atlas__accordion-heading ${title.className.trim()||'service-atlas__title'}`;heading.setAttribute('role','heading');heading.setAttribute('aria-level',String(level));heading.textContent=title.textContent;toggle.className='service-atlas__accordion-toggle';toggle.setAttribute('aria-hidden','true');answer.className='service-atlas__accordion-answer';answer.id=id;answer.setAttribute('aria-hidden','true');inner.className='service-atlas__accordion-answer-inner';answer.append(inner);parent.insertBefore(question,title);parent.insertBefore(answer,nodes[0]);question.append(heading,toggle);title.remove();nodes.forEach((node)=>inner.append(node));};
  const enhanceSmallAccordions=()=>{app.querySelectorAll('.service-atlas__small-item').forEach((item)=>{const title=item.querySelector('.service-atlas__small-name'),detail=item.querySelector('.service-atlas__small-detail'),price=item.querySelector('.service-atlas__small-price');if(!title||!detail||!price||item.querySelector('[data-atlas-accordion-question]'))return;const question=document.createElement('button'),toggle=document.createElement('span'),answer=document.createElement('div'),inner=document.createElement('div'),id=`service-atlas-small-accordion-${++accordionSerial}`;question.type='button';question.className='service-atlas__accordion-question service-atlas__small-question';question.setAttribute('aria-expanded','false');question.setAttribute('aria-controls',id);question.dataset.atlasAccordionQuestion='';toggle.className='service-atlas__accordion-toggle service-atlas__small-toggle';toggle.setAttribute('aria-hidden','true');answer.className='service-atlas__accordion-answer service-atlas__small-answer';answer.id=id;answer.setAttribute('aria-hidden','true');inner.className='service-atlas__accordion-answer-inner service-atlas__small-answer-inner';question.append(toggle,title,price);inner.append(detail);answer.append(inner);item.replaceChildren(question,answer);});};
  const enhanceTechnicalAccordions=()=>{const approved={en:['Creation, design, and development of a single web page to present your business, product, or service, with clearly organized content, sections, and contact options for easy use.','Creation, design, and development of a website with connected pages to present your business information, services, and work, with content and navigation structured around your project\'s needs.','Design and development of a mobile application based on project requirements, including the interfaces, features, and interactions needed for a clear and organized user experience.'],ar:['إنشاء وتصميم وتطوير صفحة ويب واحدة لعرض نشاطك أو منتجك أو خدمتك، مع تنظيم المحتوى والأقسام ووسائل التواصل بطريقة واضحة وسهلة الاستخدام.','إنشاء وتصميم وتطوير موقع إلكتروني يضم صفحات مترابطة لعرض معلومات نشاطك وخدماتك وأعمالك، مع تنظيم المحتوى والتنقل بين الصفحات بما يناسب احتياجات المشروع.','تصميم وتطوير تطبيق للهواتف الذكية وفق متطلبات المشروع، مع بناء الواجهات والوظائف والتفاعلات اللازمة لتقديم تجربة استخدام واضحة ومنظمة.']};app.querySelectorAll('.service-atlas__technical-item').forEach((item,index)=>{const title=item.querySelector('.service-atlas__technical-name'),detail=item.querySelector('.service-atlas__technical-description'),price=item.querySelector('.service-atlas__technical-price'),actions=item.querySelector('.service-atlas__actions');if(!title||!detail||!price)return;detail.textContent=approved[lang()][index];item.className='service-atlas__small-item';title.className='service-atlas__small-name';detail.className='service-atlas__small-detail';price.className='service-atlas__small-price';actions?.remove();});};
  const applyTechnicalSectionCopy=()=>{const section=app.querySelector('.service-atlas__technical');if(!section)return;const l=lang(),eyebrow=section.querySelector('.service-atlas__eyebrow'),title=section.querySelector('.service-atlas__title'),lead=section.querySelector('.service-atlas__lead'),note=section.querySelector('.service-atlas__technical-note');section.className='service-atlas__section service-atlas__small';if(eyebrow)eyebrow.textContent=l==='en'?'Digital Execution':'التنفيذ الرقمي';if(title)title.textContent=l==='en'?'Digital Transformation Services':'خدمات التحول الرقمي';if(lead)lead.textContent=l==='en'?"We design and develop websites and mobile applications to help you present your business and offer your services digitally, with solutions suited to your project's needs.":'نقدم خدمات تصميم وتطوير المواقع والتطبيقات لمساعدتك على عرض أعمالك وتقديم خدماتك رقميًا، مع اختيار الحل المناسب لطبيعة مشروعك واحتياجاته.';note?.remove();};
  const applyTechnicalReferenceLayout=()=>{const title=app.querySelector('#technical-title'),section=title?.closest('.service-atlas__section');if(!section)return;const intro=section.firstElementChild,lead=intro?.querySelector('.service-atlas__lead'),list=section.querySelector('.service-atlas__technical-list, .service-atlas__small-list');if(!intro||!title||!lead||!list)return;intro.querySelector('.service-atlas__eyebrow')?.remove();intro.className='service-atlas__small-head';const copy=document.createElement('div');copy.append(title);intro.replaceChildren(copy,lead);list.className='service-atlas__small-list';};
  const applyTechnicalServiceCopy=()=>{const l=lang(),names={en:['Landing Page','Multi-Page Website','Mobile App'],ar:['صفحة هبوط','موقع متعدد الصفحات','تطبيق جوال']},details={en:['Creation, design, and development of a landing page to present your business, product, or service. It can also serve as a one-page website containing the information, sections, and contact options you need.','Creation, design, and development of a multi-page website to present your business information, services, and work, with organized content and easy navigation.',"Creation, design, and development of a mobile application based on your project's needs, including the interfaces and features required for easy use."],ar:['إنشاء وتصميم وتطوير صفحة هبوط لعرض نشاطك أو منتجك أو خدمتك، ويمكن أن تكون موقعًا من صفحة واحدة يضم المعلومات والأقسام ووسائل التواصل التي تحتاجها.','إنشاء وتصميم وتطوير موقع إلكتروني يضم عدة صفحات لعرض معلومات نشاطك وخدماتك وأعمالك، مع تنظيم المحتوى وتسهيل التنقل بين الصفحات.','إنشاء وتصميم وتطوير تطبيق للهواتف الذكية حسب احتياجات مشروعك، مع تجهيز الواجهات والوظائف اللازمة لتسهيل استخدام التطبيق.']};app.querySelectorAll('.service-atlas__technical .service-atlas__small-item').forEach((item,index)=>{const title=item.querySelector('.service-atlas__small-name'),detail=item.querySelector('.service-atlas__small-detail');if(title)title.textContent=names[l][index];if(detail)detail.textContent=details[l][index];});};
  const enhancePartnerAccordions=()=>{const surface=app.querySelector('.service-atlas__partner-surface');if(!surface)return;const l=lang(),head=surface.querySelector('.service-atlas__partner-head'),group=head?.querySelector(':scope > div'),eyebrow=group?.querySelector('.service-atlas__eyebrow'),title=group?.querySelector('.service-atlas__title'),custom=head?.querySelector('.service-atlas__price'),list=surface.querySelector('.service-atlas__partner-list');if(!head||!group||!eyebrow||!title||!list)return;surface.className='service-atlas__partner-atlas';head.className='service-atlas__small-head';eyebrow.textContent=l==='en'?'Connected Execution':'تنفيذ متصل';title.textContent=l==='en'?'Partner Services':'خدمات الشركاء';if(custom)custom.textContent=l==='en'?'Custom Quote':'عرض سعر مخصص';let lead=group.querySelector('.service-atlas__partner-lead');if(!lead){lead=document.createElement('p');lead.className='service-atlas__lead service-atlas__partner-lead';group.append(lead);}lead.textContent=l==='en'?'We coordinate additional services with partners and specialized providers to help meet business needs beyond our core services. Scope and pricing are determined by the requirements of each request.':'نوفر خدمات إضافية بالتنسيق مع شركائنا ومقدمي الخدمات المتخصصين، لمساعدتك في تنفيذ احتياجات أعمالك خارج نطاق الخدمات الأساسية. يتم تحديد التفاصيل والتكلفة وفق طبيعة كل طلب.';list.className='service-atlas__small-list';list.querySelectorAll('.service-atlas__partner-item').forEach((item,index)=>{const partner=services.partners[index],itemTitle=item.querySelector('h3'),detail=item.querySelector('p'),actions=item.querySelector('.service-atlas__partner-actions');if(!partner||!itemTitle||!detail)return;item.className='service-atlas__small-item';itemTitle.className='service-atlas__small-name';detail.className='service-atlas__small-detail';itemTitle.textContent=l==='en'?partner[1]:partner[3];detail.textContent=l==='en'?partner[2]:partner[4];actions?.remove();let price=item.querySelector('.service-atlas__small-price');if(!price){price=document.createElement('span');price.className='service-atlas__small-price';item.append(price);}price.textContent=l==='en'?'On Request':'حسب الطلب';});};
  const applyPartnerDescriptionCopy=()=>{app.querySelectorAll('.service-atlas__partner-atlas .service-atlas__small-detail').forEach((detail,index)=>{detail.textContent=partnerDescriptions[lang()][index];});};
