(() => {
  const syncChapterOrder = () => {
    const contents = [...document.querySelectorAll('.ooxme-services .service-atlas__chapter-content')];
    contents.forEach((content) => {
      const lead = content.querySelector(':scope > .service-atlas__lead');
      const price = content.querySelector(':scope > .service-atlas__chapter-price');
      const deliverables = content.querySelector(':scope > .service-atlas__deliverables');
      const actions = content.querySelector(':scope > .service-atlas__actions');
      if (lead && deliverables) deliverables.before(lead);
      if (price && actions) actions.before(price);
    });

    const lists = contents.map((content) => content.querySelector(':scope > .service-atlas__deliverables')).filter(Boolean);
    const targetCount = Math.max(...lists.map((list) => list.querySelectorAll(':scope > li:not(.service-atlas__deliverable-slot)').length), 0);
    lists.forEach((list) => {
      list.querySelectorAll(':scope > .service-atlas__deliverable-slot').forEach((slot) => slot.remove());
      const missing = targetCount - list.querySelectorAll(':scope > li').length;
      for (let index = 0; index < missing; index += 1) {
        const slot = document.createElement('li');
        slot.className = 'service-atlas__deliverable-slot';
        slot.setAttribute('aria-hidden', 'true');
        list.append(slot);
      }
      const itemHeight = Math.max(...[...list.querySelectorAll(':scope > li:not(.service-atlas__deliverable-slot)')].map((item) => item.getBoundingClientRect().height), 0);
      list.querySelectorAll(':scope > .service-atlas__deliverable-slot').forEach((slot) => {
        slot.style.boxSizing = 'border-box';
        slot.style.height = `${itemHeight}px`;
      });
    });

    requestAnimationFrame(() => {
      const leads = contents.map((content) => content.querySelector(':scope > .service-atlas__lead')).filter(Boolean);
      leads.forEach((lead) => { lead.style.minHeight = ''; });
      const leadHeight = Math.max(...leads.map((lead) => lead.getBoundingClientRect().height), 0);
      leads.forEach((lead) => { lead.style.minHeight = `${leadHeight}px`; });

      const visuals = contents.map((content) => content.closest('.service-atlas__chapter')?.querySelector(':scope > .service-atlas__chapter-visual')).filter(Boolean);
      visuals.forEach((visual) => { visual.style.minHeight = ''; });
      const cardHeight = Math.max(...visuals.map((visual) => visual.getBoundingClientRect().height), 0);
      visuals.forEach((visual) => { visual.style.minHeight = `${cardHeight}px`; });
    });
  };
  syncChapterOrder();
  window.addEventListener('ooxme-language-change', syncChapterOrder);
})();

(() => {
  let activeSync = () => {};
  const syncViewportWidth = () => {
    const app = document.querySelector('.ooxme-services');
    if (app) {
      const viewportWidth = document.documentElement.clientWidth;
      const appRect = app.getBoundingClientRect();
      app.style.setProperty('--atlas-viewport-width', `${viewportWidth}px`);
      const shift = document.documentElement.dir === 'rtl' ? viewportWidth - appRect.right : -appRect.left;
      app.style.setProperty('--atlas-viewport-shift', `${shift}px`);
    }
  };
  const setupChapterCarousel = () => {
    const app = document.querySelector('.ooxme-services');
    const chapters = [...(app?.querySelectorAll(':scope > .service-atlas__chapter') || [])];
    if (!app || chapters.length !== 2) return;
    let stage = app.querySelector(':scope > .service-atlas__chapter-carousel');
    let track = stage?.querySelector(':scope > .service-atlas__chapter-track');
    if (!stage || !track) {
      stage = document.createElement('div');
      stage.className = 'service-atlas__chapter-carousel';
      track = document.createElement('div');
      track.className = 'service-atlas__chapter-track';
      stage.append(track);
      chapters[0].before(stage);
      chapters.forEach((chapter) => track.append(chapter));
    }
    if (!stage.dataset.initialized) {
      stage.dataset.index = '0';
      stage.dataset.initialized = 'true';
    }
    const reference = app.querySelector('.service-atlas__hero [data-scroll-to]');
    const getMetrics = () => {
      const gap = parseFloat(getComputedStyle(stage).getPropertyValue('--s-x')) || 18;
      const width = Math.max(0, reference?.getBoundingClientRect().width || parseFloat(getComputedStyle(app).getPropertyValue('--atlas-action-width')) || stage.clientWidth - (gap * 2));
      const rtl = document.documentElement.dir === 'rtl';
      stage.style.setProperty('--chapter-card-width', `${width}px`);
      track.style.flexDirection = rtl ? 'row-reverse' : 'row';

      // offsetLeft is the card's untransformed position inside the track. Using
      // it keeps the centering math correct for both flex directions instead of
      // guessing a different translation for RTL.
      const center = stage.clientWidth / 2;
      const bases = track.querySelectorAll(':scope > .service-atlas__chapter');
      const baseFor = (index) => center - (bases[index].offsetLeft + (width / 2));
      return { width, gap, bases, baseFor, min: Math.min(baseFor(0), baseFor(1)), max: Math.max(baseFor(0), baseFor(1)) };
    };
    const render = (translation, metrics, position = Number(stage.dataset.index || 0)) => {
      track.style.transform = `translate3d(${translation.toFixed(2)}px,0,0)`;
      const rtl = document.documentElement.dir === 'rtl';
      track.querySelectorAll(':scope > .service-atlas__chapter').forEach((chapter, cardIndex) => {
        const distance = Math.min(1, Math.abs(cardIndex - position));
        chapter.style.setProperty('--chapter-card-scale', String(1 - (distance * .06)));
        chapter.style.setProperty('--chapter-card-opacity', String(1 - (distance * .28)));
        chapter.style.direction = rtl ? 'rtl' : 'ltr';
      });
    };
    const sync = () => {
      const metrics = getMetrics();
      const index = Number(stage.dataset.index || 0);
      render(metrics.baseFor(index), metrics, index);
    };
    const syncDrag = (delta, metrics, index) => {
      const base = metrics.baseFor(index);
      const candidate = base + delta;
      const resistance = candidate < metrics.min ? metrics.min + ((candidate - metrics.min) * .28) : candidate > metrics.max ? metrics.max + ((candidate - metrics.max) * .28) : candidate;
      const position = index - (delta / Math.max(1, metrics.width + metrics.gap));
      render(resistance, metrics, Math.max(0, Math.min(1, position)));
    };
    const move = (next) => {
      stage.dataset.index = String(Math.max(0, Math.min(1, next)));
      track.classList.remove('is-dragging');
      sync();
    };
    if (!stage.dataset.bound) {
      stage.dataset.bound = 'true';
      let drag = null;
      let suppressClick = false;
      stage.addEventListener('pointerdown', (event) => {
        if (event.isPrimary === false || event.target.closest('button,a,input,select,textarea') || (event.pointerType === 'mouse' && event.button !== 0)) return;
        drag = { id: event.pointerId, startX: event.clientX, x: event.clientX, delta: 0, lastTime: performance.now(), velocity: 0, index: Number(stage.dataset.index || 0), metrics: getMetrics() };
        suppressClick = false;
        track.classList.add('is-dragging');
        stage.setPointerCapture?.(event.pointerId);
      });
      stage.addEventListener('pointermove', (event) => {
        if (!drag || drag.id !== event.pointerId) return;
        const now = performance.now();
        const deltaX = event.clientX - drag.x;
        drag.x = event.clientX;
        drag.delta = event.clientX - drag.startX;
        drag.velocity = deltaX / Math.max(1, now - drag.lastTime);
        drag.lastTime = now;
        if (Math.abs(drag.delta) > 6) suppressClick = true;
        syncDrag(drag.delta, drag.metrics, drag.index);
      });
      const finishDrag = (event, cancelled = false) => {
        if (!drag || (event.pointerId != null && drag.id !== event.pointerId)) return;
        const { delta, velocity, index, metrics, id } = drag;
        drag = null;
        track.classList.remove('is-dragging');
        stage.releasePointerCapture?.(id);
        if (cancelled) { sync(); return; }
        const threshold = Math.min(96, Math.max(32, metrics.width * .18));
        const shouldAdvance = Math.abs(delta) >= threshold || Math.abs(velocity) > .45;
        if (!shouldAdvance) { sync(); return; }
        const rtl = document.documentElement.dir === 'rtl';
        const forward = rtl ? delta > 0 : delta < 0;
        move(index + (forward ? 1 : -1));
      };
      stage.addEventListener('pointerup', (event) => finishDrag(event));
      stage.addEventListener('pointercancel', (event) => finishDrag(event, true));
      stage.addEventListener('lostpointercapture', (event) => finishDrag(event, true));
      stage.addEventListener('click', (event) => { if (suppressClick) { event.preventDefault(); event.stopPropagation(); suppressClick = false; } }, true);
    }
    stage._atlasResizeObserver?.disconnect();
    if (typeof ResizeObserver === 'function') {
      stage._atlasResizeObserver = new ResizeObserver(() => requestAnimationFrame(sync));
      stage._atlasResizeObserver.observe(stage);
      if (reference) stage._atlasResizeObserver.observe(reference);
    }
    activeSync = sync;
    syncViewportWidth();
    sync();
    document.fonts?.ready.then(sync);
  };
  window.addEventListener('resize', () => { syncViewportWidth(); activeSync(); }, { passive: true });
  setupChapterCarousel();
  window.addEventListener('ooxme-language-change', setupChapterCarousel);
})();

